INSERT INTO `articles` (`article_id`, `At_Title`, `At_content`, `At_image`, `At_sub_cat`, `At_category`, `At_status`, `Document`, `ytube`) VALUES
(223, 'Supply, Delivery and Installation of Air-Conditioning Equipment-Advertisement', '<p>\r\n\r\n</p><p class=\"Standard\" style=\"text-align:justify\"><span style=\"font-family:&quot;Bookman Old Style&quot;,serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-bidi-font-family:&quot;Times New Roman&quot;;\r\nmso-font-width:99%\">Zambian National Building Society (ZNBS)</span><span style=\"font-family:&quot;Bookman Old Style&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-bidi-font-family:&quot;Times New Roman&quot;;letter-spacing:3.85pt\"> </span><span style=\"font-family:&quot;Bookman Old Style&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-bidi-font-family:&quot;Times New Roman&quot;\">in<span style=\"mso-font-width:99%\">te</span>nd<span style=\"mso-font-width:99%\">s to engage experienced and reputable Air-Conditioning\r\nContractor for the Supply, Delivery and Installation of Air-Conditioning Equipment\r\nand Provision of the Annual Preventive Maintenance at Head office (Century\r\nHouse). </span>In<span style=\"letter-spacing:3.65pt\"> </span><span style=\"mso-font-width:99%\">t</span>hi<span style=\"mso-font-width:99%\">s</span><span style=\"letter-spacing:3.7pt\"> </span><span style=\"mso-font-width:99%\">r<span style=\"letter-spacing:.05pt\">e</span></span><span style=\"letter-spacing:.05pt\">g</span>a<span style=\"mso-font-width:99%\">r</span>d,<span style=\"letter-spacing:3.6pt\"> </span><span style=\"mso-font-width:99%\">f</span><span style=\"letter-spacing:.05pt\">u</span>nd<span style=\"mso-font-width:99%\">s</span><span style=\"letter-spacing:3.7pt\"> </span>ha<span style=\"mso-font-width:99%\">ve</span><span style=\"letter-spacing:3.7pt\"> </span>b<span style=\"mso-font-width:99%\">ee</span>n<span style=\"letter-spacing:3.65pt\"> </span><span style=\"mso-font-width:99%\">s<span style=\"letter-spacing:.05pt\">e</span>t</span><span style=\"letter-spacing:3.85pt\"> </span>a<span style=\"mso-font-width:99%\">s</span>id<span style=\"mso-font-width:99%\">e</span><span style=\"letter-spacing:3.7pt\"> </span>in\r\nits 2021/2022<span style=\"letter-spacing:3.75pt\"> </span>budg<span style=\"mso-font-width:99%\">et</span><span style=\"letter-spacing:3.7pt\"> </span><span style=\"mso-font-width:99%\">f</span>o<span style=\"mso-font-width:99%\">r</span> p<span style=\"letter-spacing:-.05pt\">a</span><span style=\"mso-font-width:99%\">y</span>m<span style=\"mso-font-width:99%\">e</span>n<span style=\"mso-font-width:99%\">ts</span><span style=\"letter-spacing:3.25pt\"> </span>o<span style=\"mso-font-width:99%\">f</span><span style=\"letter-spacing:3.15pt\"> </span><span style=\"mso-font-width:99%\">c</span>on<span style=\"mso-font-width:99%\">t<span style=\"letter-spacing:.05pt\">r</span></span>a<span style=\"mso-font-width:99%\">ct</span><span style=\"letter-spacing:3.3pt\"> </span><span style=\"mso-font-width:99%\">r<span style=\"letter-spacing:.05pt\">es</span></span>ul<span style=\"mso-font-width:99%\">t</span>ing<span style=\"letter-spacing:3.15pt\"> </span><span style=\"mso-font-width:99%\">fr</span>om<span style=\"letter-spacing:3.2pt\"> </span><span style=\"mso-font-width:99%\">t</span>hi<span style=\"mso-font-width:99%\">s</span><span style=\"letter-spacing:3.25pt\"> </span>in<span style=\"letter-spacing:.05pt;\r\nmso-font-width:99%\">v</span>i<span style=\"mso-font-width:99%\">t</span><span style=\"letter-spacing:-.05pt\">a<span style=\"mso-font-width:99%\">t</span></span>ion<span style=\"letter-spacing:3.15pt\"> </span><span style=\"mso-font-width:99%\">for the Supply,\r\nDelivery and Installation of Air-Conditioning Equipment and the Provision of\r\nthe Annual Preventive Maintenance at Head office</span>.</span><span style=\"font-family:&quot;Bookman Old Style&quot;,serif\"></span></p>\r\n\r\n<p><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:TrackMoves/>\r\n  <w:TrackFormatting/>\r\n  <w:Pun