INSERT INTO `employees_tbl` (`emp_id`, `Title`, `first_name`, `last_name`, `date_of_birth`, `email`, `mobile_number`, `whatsapp`, `address1`, `address2`, `city_town`, `genda`, `country`, `date_joined`, `jobRole`, `Qualification_level`, `qualification_Area`, `Category`, `Picture`, `brief_profile`) VALUES
(0008, 'Mr.', 'Victor ', 'Mwanza', '0000-00-00', 'mwanza@znbs.c.zm', '09987633333', '09987633333', '09987633333', '09987633333', 'Lusaka', 'Male', 'Zambia', '0000-00-00', 'Director Finance', 'Masters', '', 'Senior Management', '5f59099a809bc_219A0093-1.jpg', '														\r\n											TBA			\r\n																\r\n\r\n											'),
(0100, 'Mrs.', 'Mildred Nyamizyu ', 'Mutesa', '1986-09-09', 'e@tha.com', '0977666666', '', 'addrsss', 'address', 'Lusaka', 'Female', 'Zambia', '0000-00-00', 'Managing Director', 'Masters', '', 'Senior Management', '5f8e7a99d5138_219A0142-1.jpg', 'She is a Fellow of the Association of Chartered Certified Accountants (ACCA), and an Associate member of the Zambia Institute of Chartered Accounts (ZICA).\r\nMrs Mutesa also holds a Masters of Business Administration from Herriot Watt University, a Bachelor of Accountancy Degree from the Copperbelt University and a professional accounting qualification, ACCA.<br>\r\n\r\nCurrently a member of the Board of Trustees for the Zambia National Building Society and previously a member of the Board of Trustees for the Afrox Zambia limited Pension scheme.<br>\r\n\r\nWith over 12 years work experience, she has worked across a number of sectors including, audit assurance services, manufacturing and financial services.\r\nShe has held various positions including Director Finance and Management Accountant/Company Secretary of Afrox Zambia Limited, and Senior Auditor at  PricewaterhouseCoopers (PwC). She also had a short stint with the Bank of Zambia.\r\n\r\n												\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n											'),
(0736, '', 'Mweemba Wilber', 'Hachita', '1983-12-12', 'mw33mba@gmail.com', '+260977519229', '+260977519229', '16514/1080', 'Kamwala South', 'Lusaka', 'Male', 'Zambia', '2013-03-22', 'ICT Teacher', 'Bachelors Digree', 'Computer Science', 'Employee', 'mweemba.jpg', ''),
(0989, 'Mr.', 'Christopher Lubumbe ', 'Kapoma ', '1900-09-09', 'e@tha.com', '0977666666', '', 'addrsss', 'address', 'Lusaka', 'Male', 'Zambia', '0000-00-00', 'Director Human Resources', 'Digree', '', 'Senior Management', '62f4c1a7ef344_download (3).png', 'Degree in Human Resources Management\r\nHigher Diploma in Human Resources Management\r\n\r\nFull member of the Zambia Institute of Human\r\n\r\nResources Management (ZIHRM)\r\n\r\n\r\nMr Kapoma is a qualified and experienced Human Resources Practitioner with 17 years of work experience in Human<br>\r\n\r\nResources  Management and Administration of which 9 years is at Executive Management level gained mostly from the financial and transport sectors.<br>\r\n\r\nPreviously he worked as Director Human Resources for Railway Systems of Zambia and Zambia Railways Limited. He has also worked for National Airports Corporation Limited, Project Concern International (USAID Funded) and Commence Bank in the infancy of his career.<br>\r\n\r\nHe served as a Board Committee Member for the Human Resources, Legal and Customer Service Committee for Zambia Electricity Supply Corporation Limited (ZESCO). He is currently a Board Committee Member for the Human Capital and Administration Committee for Road Development Agency (RDA).														\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n											'),
(3434, 'Mrs.', 'Vivian ', 'Milumbe', '1900-09-09', 'e@tha.com', '0977666666', '', 'N/A', 'N/A', 'Lusaka', 'Male', 'Zambia', '0000-00-00', 'Chief Operations Officer', 'Masters', '', 'Senior Management', '5f59085433ebb_219A0134-1.jpg', 'Mrs Vivian Milumbe is a qualified and experienced Information and Communications Technology (ICT) professional, who has worked for reputable financial institutions in Zambia. Mrs Milumbe holds a Master of Business Administration Degree from Herriot Watt University, Bsc in Computing from Greenwich University and an advanced Professional Diploma in Banking from Zambia Institute of Banking and Financial Services (ZIBFS).<br>\r\n\r\nShe has over 20 years of experience in the financial services industry having worked<br>\r\nfor Cavmont Capital Bank as ICT Manager, Pan African Building Society as Chief Operations Officer and Bayport Financial Services as Head of ICT.<br>\r\n\r\n\r\nHer overall experience includes Managing Information systems environments, Banking and Treasury Operations and managing alternative service delivery channels in the Financial Industry. She is a member of the Institute of Directors, Information and Communication Association of Zambia and the Institute of Banking and Financial Services.														\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n											'),
(8989, 'Mr.', 'Chanda', 'Mubanga', '1986-09-09', 'chanda.mubanga@znbs.co.zm', '909879887', '', 'N/A', 'N/A', 'Lusaka', 'Male', 'Zambia', '0000-00-00', 'Marketing', 'Digree', '', 'Employee', '5f1746b7cf393_avator.png', '														\r\n														\r\n																\r\n\r\n				nmnmmmm							'),
(9938, 'Mr.', 'Fortune', 'Mukuka', '1900-09-09', 'e@tha.com', '0977666666', '', 'N/A', 'N/A', 'Lusaka', 'Male', 'Zambia', '0000-00-00', 'Director Banking and Mortgage', 'Masters', '', 'Senior Management', '62f4be68e10c5_download (2).png', ''),
(98090, 'Mr.', 'Elijah Esau ', 'Chulu', '1986-09-09', 'e@tha.com', '0977666666', '', 'N/A', 'N/A', 'Lusaka', 'Male', 'Zambia', '0000-00-00', 'Director Risk', 'Masters', '', 'Senior Management', '62f4bf25c4c99_ZNBS-4.jpg', 'M.BA. Finance and Accounting from National University, San Diego, California USA, B.A Economics from University of Zambia. He also holds certifications in risk and project management.\r\n\r\nMr. Chulu has over 17 years of both local and international banking experience, having worked for Barclays Bank and Europe Arab Bank in the UK and Barclays Bank Zambia.\r\n\r\nHis overall experience in banking includes, Retail and Corporate Sales, Retail Risk Management, International Trade and Cash Management, Business Support and Restructuring as well as Leverage Finance.<br>\r\n\r\nIn his previous role, he worked as Head of Retail Credit Risk for Barclays Bank Zambia PLC  for the last 8 years and was a member of the Executive Leadership Team.<br>\r\n\r\nMr. Chulu is also a Board Member for World Vision Zambia and a member of the Audit and Risk Committee.														\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n																									\r\n														\r\n																\r\n\r\n											'),
(894989, 'Ms.', 'Mutinta ', 'Syulikwa', '1900-09-09', 'e@tha.com', '0977666666', '', 'N/A', 'N/A', 'Lusaka', 'Female', 'Zambia', '0000-00-00', 'Society Secretary', 'Digree', '', 'Senior Management', '5ec0ccaf02ff4_act.jpg', 'Holder of a Bachelor of Law Degree and a member of the Law Association of Zambia.<br>\r\nShe has over 8 years experience in law having practised as an advocate in the private sector prior before joining the Society.\r\n											');
