INSERT INTO `property` (`prop_id`, `prop_category_id`, `property_condition`, `location_province`, `location_Area`, `type`, `plot_size_length`, `plot_size_width`, `price_range`, `no_bathrooms`, `no_bedrooms`, `description`, `status`, `owner_id`, `featured`, `Date_posted`, `Rent_Sale`) VALUES
(2, '10', 'Reconditioned', 'Copper-belt', 'Kamenza, Chililabombwe (ON OFFER)', '10', '50', '60', 400000, 2, 10, 'This is a residential standalone three bedroom house located\r\nin Honey Bird, Kamenza township, Chililabombwe. Ancillary\r\nstructures on site include a chicken run. It is situated approximately\r\n1.5 Km south of the Central Business District of Chililabombwe.', 'Sold', '1', 'Yes', '2021-01-18', 'Rent_sale'),
(3, '12', 'Reconditioned', 'Lusaka', 'Meanwood Ndeke', '12', '30', '30', 852000, 10, 2, 'The subject property is a residential standalone three bedroom(master\r\nself-contained) house enclosed in a concrete boundary wall with steel\r\npalisade fencing to two sides and six strand electric wire atop accessible\r\nby way of a steel motorized sliding gate. It is located in Meanwood Ndeke\r\napproximately 25Km from the Central Business District of Lusaka.', 'Sold', '1', 'No', '2021-01-18', 'Rent_sale'),
(4, '12', 'Reconditioned', 'Copper-belt', 'KAMENZA TOWNSHIP', '12', '60', '50', 400000, 7, 1, 'This is a residential standalone three bedroom house located\r\nin Honey Bird, Kamenza township, Chililabombwe. Ancillary\r\nstructures on site include a chicken run. It is situated approximately\r\n1.5 Km south of the Central Business District of Chililabombwe.', 'Not available', '1', 'No', '2021-01-18', 'Rent_sale'),
(5, '12', 'Reconditioned', 'Southern', 'Kabobola, Mazabuka', '12', '40', '30', 45000, 1, 5, '1. Plot No.89\r\nThe subject property is a low cost house comprising a three bedroom incomplete\r\nhouse with a lounge, kitchen room, circulation passage and a verandah. Annexed\r\nbuilding comprises two rooms and a verandah. The property is located in a\r\nhigh density residential area of Kabobola in Mazabuka, Southern Province.', 'Sold', '1', 'No', '2021-04-30', 'Rent_sale'),
(6, 'Sell', 'Reconditioned', 'Southern', 'Nakambala, Mazabuka', '12', '30', '25', 408501, 5, 1, 'The subject property is a low cost house comprising a three bedroom incomplete house with a lounge, kitchen room, circulation passage and a verandah. Annexed building comprises two rooms and a verandah. The property is located in a\r\nhigh density residential area of Kabobola in Mazabuka, Southern Province.', 'Sold', '1', 'Yes', '2021-05-11', 'Sell');
